import { build } from "esbuild";
import { execSync } from "node:child_process";
import { cpSync, mkdirSync, rmSync, writeFileSync } from "node:fs";

// Vercel's zero-config /api detection scans the pre-build source tree, so a
// serverless function file generated by this script (as api/index.js used
// to be) is invisible to it - see the sibling investigation in git history.
// Writing directly to .vercel/output (the Build Output API) sidesteps that:
// Vercel deploys whatever is here as-is, no detection involved.
const outDir = ".vercel/output";
rmSync(outDir, { recursive: true, force: true });

execSync("pnpm --filter web run build", { stdio: "inherit" });

const funcDir = `${outDir}/functions/api/index.func`;
mkdirSync(funcDir, { recursive: true });

// @redline/scenarios and @redline/shared ship raw .ts as their package.json
// "main" with no build step, which only works when something (tsx, Vite)
// transforms TS-in-node_modules on the fly - Vercel's Node runtime doesn't.
// Bundling everything (no externals) means the function is one
// self-contained file with no runtime node_modules dependency at all, so
// none of that matters here.
await build({
  entryPoints: ["apps/api/src/vercelHandler.ts"],
  bundle: true,
  platform: "node",
  format: "esm",
  target: "node24",
  outfile: `${funcDir}/index.js`,
  banner: {
    js: "import { createRequire as __createRequire } from 'node:module'; const require = __createRequire(import.meta.url);",
  },
});

writeFileSync(
  `${funcDir}/.vc-config.json`,
  JSON.stringify({ runtime: "nodejs24.x", handler: "index.js", launcherType: "Nodejs" }),
);
writeFileSync(`${funcDir}/package.json`, JSON.stringify({ type: "module" }));

mkdirSync(`${outDir}/static`, { recursive: true });
cpSync("apps/web/dist", `${outDir}/static`, { recursive: true });

writeFileSync(
  `${outDir}/config.json`,
  JSON.stringify({
    version: 3,
    routes: [
      { src: "^/health$", dest: "/api" },
      { src: "^/api(?:/.*)?$", dest: "/api" },
      { handle: "filesystem" },
      { src: "/(.*)", dest: "/index.html" },
    ],
  }),
);
